524	    name: "🏪 摆地摊创业",
525	    desc: "去批发市场进点货，到商业区摆摊卖。风险高收入高。",
526	    icon: "🏪",
527	    costEstimate: 200,
528	    payEstimate: "200~500",
529	    handler: () => {
