570	/** 汇款模态框 */
571	function showRemitModal() {
572	  const state = StateManager.getState();
573	  showModal({
574	    title: "💌 给家里汇款",
575	    body: `<p>当前现金: ¥${state.resources.cash.toLocaleString()}</p>
576	           <p style="font-size:11px;color:var(--text-secondary);">每汇 100 元，心情+3，名气+0.5。</p>
577	           <label>汇款金额: <input id="remit-amount" type="number" min="100" max="${state.resources.cash}" value="200" style="width:100%;padding:8px;margin-top:8px;background:var(--bg-input);border:1px solid var(--border);color:var(--text-primary);border-radius:4px;"></label>`,
578	    buttons: [
579	      { text: "取消", cls: "", callback: () => {} },
580	      {
581	        text: "汇款",
582	        cls: "btn-primary",
583	        callback: () => {
584	          const amt = Math.max(
585	            0,
586	            Math.min(
587	              state.resources.cash,
588	              parseInt(document.getElementById("remit-amount")?.value || 0),
589	            ),
590	          );
591	          if (amt < 100) {
592	            StateManager.addMessage("💌 至少汇 100 块。", "warning");
593	            return;
594	          }
595	          state.resources.cash -= amt;
596	          state.needs.happiness = Math.min(
597	            100,
598	            state.needs.happiness + (amt / 100) * 3,
599	          );
600	          state.status.fame = Math.min(
601	            100,
602	            state.status.fame + (amt / 100) * 0.5,
603	          );
604	          StateManager.addMessage(
605	            `💌 给家里汇了 ¥${amt.toLocaleString()}，爸妈很高兴。`,
606	            "success",
607	          );
608	          document.querySelector(".modal-overlay")?.remove();
609	          renderAll();
610	        },
611	      },
612	    ],
613	  });
614	}
