617	function showYuEBaoModal() {
618	  const state = StateManager.getState();
619	  const yue = state.flags.yuEBao || 0;
620	  const todayInterest = Math.floor(yue * 0.0001);
621	  showModal({
622	    title: "💰 余额宝理财",
623	    body: `
624	      <p>当前余额宝: <strong style="color:var(--success);">¥${yue.toLocaleString()}</strong></p>
625	      <p>今日收益预估: <strong>+¥${todayInterest}</strong>（日息 0.01%）</p>
626	      <p>现金: ¥${state.resources.cash.toLocaleString()}</p>
627	      <label>转入金额: <input id="yue-amount" type="number" min="100" max="${state.resources.cash}" value="${Math.floor(state.resources.cash)}" style="width:100%;padding:8px;margin-top:8px;background:var(--bg-input);border:1px solid var(--border);color:var(--text-primary);border-radius:4px;"></label>
628	    `,
629	    buttons: [
630	      { text: "取消", cls: "", callback: () => {} },
631	      {
632	        text: "全部转出",
633	        cls: "btn-warning",
634	        callback: () => {
635	          state.resources.cash += yue;
636	          state.flags.yuEBao = 0;
637	          StateManager.addMessage(
638	            `💰 从余额宝转出 ¥${yue.toLocaleString()}。`,
639	            "info",
640	          );
641	          document.querySelector(".modal-overlay")?.remove();
642	          renderAll();
643	        },
644	      },
645	      {
646	        text: "确认转入",
647	        cls: "btn-success",
648	        callback: () => {
649	          const amt = Math.max(
650	            0,
651	            Math.min(
652	              state.resources.cash,
653	              parseInt(document.getElementById("yue-amount")?.value || 0),
654	            ),
655	          );
656	          if (amt < 100) {
657	            StateManager.addMessage("💰 至少转入 100 块。", "warning");
658	            return;
659	          }
660	          state.resources.cash -= amt;
661	          state.flags.yuEBao = (state.flags.yuEBao || 0) + amt;
662	          StateManager.addMessage(
663	            `💰 转入余额宝 ¥${amt.toLocaleString()}。`,
664	            "success",
665	          );
666	          document.querySelector(".modal-overlay")?.remove();
667	          renderAll();
668	        },
669	      },
670	    ],
671	  });
672	}
