/**
 * 交易商品定义
 *
 * 商品格式: { id, name, basePrice, unit, category }
 * category: daily | food | luxury | clothing | electronics | scrap
 */

const GOODS = [
  {
    id: "water",
    name: "瓶装水",
    basePrice: 1.5,
    unit: "瓶",
    category: "daily",
  },
  {
