11	  return {
12	    // --- 元数据 ---
13	    version: "1.0.0",
14	    createdAt: now,
15	    lastPlayedAt: now,
16	    playTime: 0,
17	
18	    // --- 玩家身份 ---
19	    player: {
20	      name: "无名",
21	      gender: "male",
22	      age: 20,
23	      birthday: { month: 6, day: 15 },
