1119	/**
1120	 * 技能加权收入倍率
1121	 * 根据工作类型，玩家相关技能等级会提升收入。
1122	 * 每10级技能提升约5%收入，上限+50%（Lv.100）。
1123	 * 减少纯RNG依赖，奖励技能投资。
1124	 */
1125	function getSkillPayBonus(jobId, state) {
1126	  const s = state.skills;
1127	  const skillMap = {
1128	    // 维修类 -> repair 技能
1129	    repair_service: { key: "repair", weight: 1.0 },
1130	    skilled_labor_construction: { key: "repair", weight: 0.6 },
1131	    // 摆摊/销售类 -> sales 技能
1132	    street_vending_food: { key: "sales", weight: 0.8 },
1133	    street_vending_goods: { key: "sales", weight: 1.0 },
1134	    food_stall: { key: "cooking", weight: 0.9 },
1135	    // 配送类 -> agility
1136	    delivery_rider: { key: "agility", weight: 0.7 },
1137	    package_delivery: { key: "agility", weight: 0.6 },
1138	    // 仓库/体力类 -> physique
1139	    warehouse_worker: { key: "physique", weight: 0.5 },
1140	    manual_labor_construction: { key: "physique", weight: 0.6 },
1141	    factory_work_assembly: { key: "physique", weight: 0.5 },
1142	    // 保安 -> physique
1143	    security_guard: { key: "physique", weight: 0.3 },
1144	    // 理发 -> repair(手艺)
1145	    barber: { key: "repair", weight: 0.5 },
1146	    // 清洁 -> physique
1147	    cleaning_service: { key: "physique", weight: 0.3 },
1148	    // 家教 -> intelligence
1149	    tutoring: { key: "intelligence", weight: 0.8 },
1150	    // 表演 -> sales(吸引打赏)
1151	    street_performer: { key: "sales", weight: 0.5 },
1152	  };
1153	
1154	  const mapping = skillMap[jobId];
1155	  if (!mapping) return 1.0;
1156	
1157	  // 兼容属性键和技能键
1158	  let effectiveLevel = 0;
1159	  const attrKeys = ["physique", "intelligence", "agility", "mental"];
1160	  if (attrKeys.includes(mapping.key)) {
1161	    effectiveLevel = state.player[mapping.key] || 0;
1162	  } else if (s[mapping.key]) {
1163	    effectiveLevel = s[mapping.key].level || 0;
1164	  }
1165	
1166	  // 每10级 +5%收入，权重调节
1167	  const bonus = (effectiveLevel / 10) * 0.05 * mapping.weight;
1168	  return 1.0 + Math.max(0, Math.min(0.35, bonus));
1169	}
