545	function createActionCard(action, state) {
546	  const card = document.createElement("div");
547	  card.className = "action-card";
548	  if (action.disabled) {
549	    card.classList.add("disabled");
550	  }
551	
552	  card.innerHTML = `
553	    <div class="card-icon">${action.icon}</div>
554	    <div class="card-title">${action.name}</div>
555	    <div class="card-desc">${action.desc}</div>
556	    <div class="card-meta">
557	      ${action.payEstimate ? `<span class="pay-estimate">💰 ¥${action.payEstimate}</span>` : ""}
558	      ${action.costEstimate ? `<span class="cost-estimate">💸 ¥${action.costEstimate}</span>` : ""}
559	      ${action.reqFail ? `<span class="req-fail">⚠ ${action.reqFail}</span>` : ""}
560	    </div>
561	  `;
562	
563	  if (!action.disabled) {
564	    card.addEventListener("click", () => {
565	      if (action.handler) {
566	        action.handler();
567	        renderAll();
568	      }
569	    });
570	  }
571	
572	  return card;
573	}
