const apColor = ap > 50 ? "var(--success)" : ap > 20 ? "var(--warning)" : "var(--danger)";
div.innerHTML = `
  <span>📅 第 <strong>${state.player.day}</strong> 天</span>
  <span>|</span>
  <span class="time-slot-badge ${slot}">${slotNames[slot]}</span>
