function renderNeedsBars(state) {
  const n = state.needs;
  const s = state.status;
  const p = state.player;
  setStatBar("stat-hunger", n.hunger, "hunger");
  setStatBar("stat-fatigue", n.fatigue, "fatigue");
  setStatBar("stat-hygiene", n.hygiene, "hygiene");
  setStatBar("stat-happiness", n.happiness, "happiness");
  setStatBar("stat-health", s.health, "health");
  setStatBar("stat-fame", s.fame, "fame");
  // 行动力（低AP时闪烁警告）
  const apPct = (p.actionPoints / (p.maxActionPoints || 100)) * 100;
  setStatBar("stat-ap", apPct, "ap-bar");
  const apVal = document.querySelector("#stat-ap .stat-value");
  if (apVal) {
    apVal.textContent = p.actionPoints + "/" + (p.maxActionPoints || 100);
  }
  // 低AP：整行高亮闪烁
  const apRow = document.getElementById("stat-ap");
  if (apRow) {
    var lowAp = p.actionPoints > 0 && p.actionPoints <= 30;
    if (lowAp) {
      apRow.style.cssText = "padding:4px 0;border:2px solid #ff5722;border-radius:4px;background:rgba(255,87,34,0.12);box-shadow:0 0 10px rgba(255,87,34,0.35);animation:ap-blink-border 0.7s infinite;";
      // AP条变红
      var apBar = apRow.querySelector(".stat-bar");
      if (apBar) apBar.style.background = "linear-gradient(90deg, #ff5722, #ff9800)";
    } else {
      apRow.style.cssText = "";
      var apBar2 = apRow.querySelector(".stat-bar");
      if (apBar2) apBar2.style.background = "";
    }
  }
}

