file.content:
@media (max-width: 768px) {
  #app {
    grid-template-columns: 1fr;
    grid-template-areas:
      "header"
      "main";
  }

  #sidebar {
    position: fixed;
    left: -100%;
    top: var(--header-height);
    bottom: 0;
    width: 280px;
    z-index: 200;
    transition: left 0.3s ease;
    box-shadow: 2px 0 8px rgba(0, 0, 0, 0.3);
  }

  #sidebar.open {
    left: 0;
  }

  .action-cards {
    grid-template-columns: 1fr;
  }

  .header-stats {
    gap: 10px;
  }

  .header-stat .label {
    display: none;
  }

  #mobile-menu-btn {
    display: flex !important;
  }
}

#mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 20px;
  cursor: pointer;
  padding: 4px;
}

@media (min-width: 769px) {
  #mobile-menu-btn {
    display: none !important;
  }
}

/* ====== Tutorial System ====== */
.tutorial-overlay .modal-box {
  border: 2px solid var(--accent);
  box-shadow: 0 0 40px rgba(102, 126, 234, 0.3);

