input.new_string:
function renderCorpTab(state, parent) {
  if (state.player.phase !== "corporate") {
    parent.innerHTML =
      '<p style="color:var(--text-muted);text-align:center;padding:40px;">🔒 进入职场后解锁</p>';
    return;
  }

  const c = state.corporate;
  const div = document.createElement("div");

  // === 职场核心信息 ===
  var companyName = (c.company && c.company.name) || "当前公司";
  var quartersTotal = Math.max(1, Math.floor((state.player.day - (c.joinedDay || 0)) / 30));

  var summaryHtml =
    '<h3 style="color:var(--text-muted);margin-bottom:12px;">🏢 职场信息 — ' + companyName + ' | 入职第' + quartersTotal + '个季度</h3>' +
    '<div class="action-cards" style="grid-template-columns:repeat(auto-fill,minmax(180px,1fr))">' +
    '<div class="action-card"><div class="card-title">职级</div><div class="card-desc" style="font-size:20px;color:var(--accent);font-weight:700;">' + c.rank + '</div></div>' +
    '<div class="action-card"><div class="card-title">本季剩余行动</div><div class="card-desc" style="font-size:16px;color:var(--warning);">' + ((c.quarterlyActions || 3) - (c.actionsUsed || 0)) + ' / ' + (c.quarterlyActions || 3) + '</div></div>' +
    '<div class="action-card"><div class="card-title">连续C次数</div><div class="card-desc" style="font-size:14px;color:' + (c.consecutiveC >= 2 ? 'var(--danger)' : 'var(--text-muted)') + ';">' + (c.consecutiveC || 0) + '</div></div>';

  // 公司股票
  if (c.stocks && c.stocks.length > 0) {
    var stockVal = 0;
    for (var si = 0; si < c.stocks.length; si++) {
      var s = c.stocks[si];
      stockVal += (s.currentPrice || s.grantPrice) * (s.shares || 0);
    }
    summaryHtml += '<div class="action-card"><div class="card-title">公司股票</div><div class="card-desc">' + c.stocks.length + ' 持仓 | 市值 <strong style="color:var(--accent);">¥' + Math.round(stockVal).toLocaleString() + '</strong></div></div>';
  }

  summaryHtml += '</div>';

  // === 绩效明细 ===
  if (c.perfHistory && c.perfHistory.length > 0) {
    var perfRows = "";
    var grades = {"S": "var(--success)", "A": "#2ecc71", "B": "var(--warning)", "C": "var(--danger)"};
    for (var pi = c.perfHistory.length - 1; pi >= Math.max(0, c.perfHistory.length - 6); pi--) {
      var pr = c.perfHistory[pi];
      var gColor = grades[pr.grade] || "var(--text-muted)";
      perfRows +=
        '<div style="display:flex;justify-content:space-between;padding:5px 8px;border-bottom:1px solid rgba(255,255,255,0.03);font-size:11px;">' +
        '<span>Y' + (pr.year || '?') + ' Q' + (pr.quarter || '?') + '</span>' +
        '<span style="color:' + gColor + ';font-weight:600;">' + pr.grade + '</span>' +
        '<span style="color:var(--text-muted);">评分 ' + (pr.score || '?') + '</span>' +
        '</div>';
    }
    summaryHtml +=
      '<div style="margin-top:12px;padding:10px 12px;background:var(--bg-card);border:1px solid var(--border);border-radius:8px;">' +
      '<h4 style="font-size:12px;color:var(--text-muted);margin-bottom:6px;">📊 绩效记录（最近6次）</h4>' +
      '<div style="display:flex;justify-content:space-between;padding:3px 8px;font-size:10px;color:var(--text-muted);border-bottom:1px solid var(--border);"><span>季度</span><span>评级</span><span>评分</span></div>' +
      perfRows + '</div>';
  }

  // === 团队视图 ===
  if (c.team && c.team.length > 0) {
    var teamRows = "";
    var totalOutput = 0;
    for (var ti = 0; ti < c.team.length; ti++) {
      var tm = c.team[ti];
      var output = (tm.productivity || 0.5) * (tm.skill || 50);
      totalOutput += output;
      var loyaltyColor = (tm.loyalty || 50) >= 70 ? "var(--success)" : (tm.loyalty || 50) >= 40 ? "var(--warning)" : "var(--danger)";
      teamRows +=
        '<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 8px;border-bottom:1px solid rgba(255,255,255,0.03);font-size:11px;">' +
        '<span style="font-weight:600;">👤 ' + (tm.name || '成员') + '</span>' +
        '<span style="color:var(--text-muted);font-size:10px;">' + (tm.role || '') + '</span>' +
        '<span style="color:var(--text-muted);">能力 ' + (tm.skill || 50) + '</span>' +
        '<span style="color:' + loyaltyColor + ';">忠诚 ' + (tm.loyalty || 50) + '</span>' +
        '<span style="color:var(--accent);">产出 ' + Math.round(output) + '</span>' +
        '</div>';
    }
    summaryHtml +=
      '<div style="margin-top:12px;padding:10px 12px;background:var(--bg-card);border:1px solid var(--border);border-radius:8px;">' +
      '<h4 style="font-size:12px;color:var(--text-muted);margin-bottom:6px;">👥 团队 (' + c.team.length + '人 | 总产出 <strong style="color:var(--accent);">' + Math.round(totalOutput) + '</strong>)</h4>' +
      '<div style="display:flex;justify-content:space-between;padding:3px 8px;font-size:10px;color:var(--text-muted);border-bottom:1px solid var(--border);"><span>成员</span><span>角色</span><span>能力</span><span>忠诚</span><span>产出</span></div>' +
      teamRows + '</div>';
  }

  div.innerHTML = summaryHtml;
  parent.appendChild(div);
}

