374	function buyInvStock(symbol, shares) {
375	  var state = StateManager.getState();
376	  var inv = state.investment;
377	  var m = inv.stockMarket[symbol];
378	  if (!m) return;
379	  var cost = Math.round(m.price * shares * 100) / 100;
380	  if (state.resources.cash < cost) {
381	    StateManager.addMessage("现金不足", "danger");
382	    return;
383	  }
384	  state.resources.cash -= cost;
385	  var h = inv.stockHoldings.find(function (s) {
386	    return s.symbol === symbol;
387	  });
388	  if (h) {
389	    var total = h.shares + shares;
390	    h.avgPrice =
391	      Math.round(((h.avgPrice * h.shares + cost) / total) * 100) / 100;
392	    h.shares = total;
393	  } else
394	    inv.stockHoldings.push({
395	      symbol: symbol,
396	      shares: shares,
397	      avgPrice: m.price,
398	    });
399	  StateManager.addMessage("买入 " + symbol + " " + shares + "股", "success");
400	}
401	
402	function sellInvStock(symbol, shares) {
403	  var state = StateManager.getState();
404	  var inv = state.investment;
405	  var h = inv.stockHoldings.find(function (s) {
406	    return s.symbol === symbol;
407	  });
408	  if (!h || h.shares < shares) {
409	    StateManager.addMessage("持仓不足", "danger");
410	    return;
411	  }
412	  var m = inv.stockMarket[symbol];
413	  var revenue = Math.round(m.price * shares * 100) / 100;
414	  state.resources.cash += revenue;
415	  h.shares -= shares;
416	  if (h.shares <= 0)
417	    inv.stockHoldings = inv.stockHoldings.filter(function (s) {
418	      return s.symbol !== symbol;
419	    });
420	  StateManager.addMessage("卖出 " + symbol + " " + shares + "股", "success");
421	}
422	
423	function buyBtc(amount) {
424	  var state = StateManager.getState();
425	  var inv = state.investment;
426	  var cost = Math.round(inv.btcPrice * amount * 100) / 100;
427	  if (state.resources.cash < cost) {
428	    StateManager.addMessage("现金不足", "danger");
429	    return;
430	  }
431	  state.resources.cash -= cost;
432	  // 追踪加权平均成本
433	  var oldTotal = (inv.btcAvgCost || 0) * (inv.btcHoldings || 0);
434	  var newTotal = oldTotal + cost;
435	  inv.btcHoldings = Math.round((inv.btcHoldings + amount) * 10000) / 10000;
436	  inv.btcAvgCost = inv.btcHoldings > 0 ? Math.round(newTotal / inv.btcHoldings * 100) / 100 : 0;
437	  StateManager.addMessage("买入 " + amount + " BTC, 均价 ¥" + inv.btcAvgCost.toLocaleString(), "success");
438	}
439	
440	function sellBtc(amount) {
441	  var state = StateManager.getState();
442	  var inv = state.investment;
443	  if (inv.btcHoldings < amount) {
444	    StateManager.addMessage("持仓不足", "danger");
445	    return;
446	  }
447	  var curPrice = inv.btcPrice;
448	  var revenue = Math.round(curPrice * amount * 100) / 100;
449	  var avgCost = inv.btcAvgCost || 0;
450	  var pl = avgCost > 0 ? Math.round((curPrice - avgCost) * amount) : 0;
451	  var plStr = pl !== 0 ? (pl > 0 ? " 📈+" : " 📉") + pl : "";
452	  state.resources.cash += revenue;
453	  inv.btcHoldings = Math.round((inv.btcHoldings - amount) * 10000) / 10000;
454	  // 清仓时重置成本
455	  if (inv.btcHoldings <= 0) inv.btcAvgCost = 0;
456	  StateManager.addMessage("卖出 " + amount + " BTC, 到手 ¥" + Math.round(revenue).toLocaleString() + plStr, "success");
457	}
458	
459	function buyProperty(propId) {
460	  var state = StateManager.getState();
461	  var inv = state.investment;
462	  var prop = PROPERTIES.find(function (p) {
463	    return p.id === propId;
464	  });
465	  if (!prop) return;
466	  if (state.resources.cash < prop.price) {
467	    StateManager.addMessage("现金不足", "danger");
468	    return;
469	  }
470	  state.resources.cash -= prop.price;
471	  inv.properties.push({
472	    id: prop.id,
473	    name: prop.name,
474	    type: prop.type,
475	    appreciation: prop.appreciation,
476	    rent: prop.rent,
