    holdingsDiv.style.cssText = "margin-bottom:12px;padding:12px;background:rgba(243,156,18,0.06);border:1px solid var(--warning);border-radius:8px;";
    var totalCarVal = 0, totalCarPL = 0;
    var holdingRows = "";
    for (var i = 0; i < list.length; i++) {
      var c = list[i];
      var cur = c.currentPrice || c.buyPrice;
