    type: prop.type,
    appreciation: prop.appreciation,
    rent: prop.rent,
    buyPrice: prop.price,
    currentPrice: prop.price,
    buyDay: state.player.day,
  });
  StateManager.addMessage("购入" + prop.name, "success");
}

