260	function initInvestment(state) {
261	  var inv = state.investment;
262	  if (!inv) return;
263	  var initialized = false;
264	  for (var i = 0; i < INV_STOCKS.length; i++) {
265	    var s = INV_STOCKS[i];
266	    if (!inv.stockMarket[s.symbol]) {
267	      initialized = true;
268	      var mPrice = s.basePrice * (0.85 + Math.random() * 0.3);
269	      var history = [];
270	      // 回溯生成 5-8 个历史数据点，保证首日就有小曲线
271	      var seedPrice = mPrice * (0.9 + Math.random() * 0.2);
272	      var numPoints = 5 + Math.floor(Math.random() * 4);
273	      for (var k = 0; k < numPoints; k++) {
274	        seedPrice =
275	          seedPrice * (1 + s.trend + (Math.random() - 0.5) * 2 * s.volatility);
276	        seedPrice = Math.max(0.5, seedPrice);
277	        history.push({
278	          day: state.player.day - numPoints + k,
279	          price: Math.round(seedPrice * 100) / 100,
280	        });
281	      }
282	      history.push({
283	        day: state.player.day,
284	        price: Math.round(mPrice * 100) / 100,
285	      });
286	      inv.stockMarket[s.symbol] = {
287	        price: Math.round(mPrice * 100) / 100,
288	        history: history,
289	      };
290	    }
291	  }
292	  if (inv.btcPrice <= 0) inv.btcPrice = 200000;
293	  if (!inv.btcHistory) inv.btcHistory = [];
294	  // 同样为 BTC 生成回溯历史
295	  if (inv.btcHistory.length === 0 && inv.btcPrice > 0) {
296	    var btcSeed = inv.btcPrice * (0.85 + Math.random() * 0.3);
297	    var btcPoints = 5 + Math.floor(Math.random() * 4);
298	    for (var b = 0; b < btcPoints; b++) {
299	      btcSeed = btcSeed * (1 + (Math.random() - 0.5) * 0.08);
300	      btcSeed = Math.max(1000, btcSeed);
301	      inv.btcHistory.push({
302	        day: state.player.day - btcPoints + b,
303	        price: Math.round(btcSeed),
304	      });
305	    }
306	    inv.btcHistory.push({ day: state.player.day, price: inv.btcPrice });
307	    if (inv.btcHistory.length > 30) inv.btcHistory.shift();
308	  }
309	  inv.lastTickDay = state.player.day;
310	}
311	
312	function tickInvestmentDaily(state) {
313	  var inv = state.investment;
314	  if (!inv || inv.lastTickDay >= state.player.day) return;
315	  inv.lastTickDay = state.player.day;
316	
317	  // 股票/贵金属/期货/基金每日波动
318	  for (var i = 0; i < INV_STOCKS.length; i++) {
319	    var s = INV_STOCKS[i];
320	    var m = inv.stockMarket[s.symbol];
321	    if (!m) continue;
322	    m.price = Math.max(
323	      0.01,
324	      m.price * (1 + s.trend + (Math.random() - 0.5) * 2 * s.volatility),
325	    );
326	    m.price = Math.round(m.price * 100) / 100;
327	    m.history.push({ day: state.player.day, price: m.price });
328	    if (m.history.length > 20) m.history.shift();
329	  }
330	
331	  // 比特币
332	  if (inv.btcPrice > 0) {
333	    inv.btcFearGreed = Math.max(
334	      5,
335	      Math.min(95, (inv.btcFearGreed || 50) + (Math.random() - 0.5) * 10),
336	    );
337	    inv.btcPrice = Math.max(
338	      1000,
339	      Math.round(
340	        inv.btcPrice *
341	          (1 +
342	            (Math.random() - 0.5) * 0.08 +
343	            ((inv.btcFearGreed - 50) / 50) * 0.02),
344	      ),
345	    );
346	    if (!inv.btcHistory) inv.btcHistory = [];
347	    inv.btcHistory.push({ day: state.player.day, price: inv.btcPrice });
348	    if (inv.btcHistory.length > 30) inv.btcHistory.shift();
349	
350	    if (state.player.day - inv.btcHalvingDay > 1460) {
351	      inv.btcHalvingDay = state.player.day;
352	      inv.btcFearGreed = Math.min(95, inv.btcFearGreed + 20);
353	      StateManager.addMessage("比特币减半事件！", "event");
354	    }
355	  }
356	
357	  // 房产
358	  for (var p = 0; p < (inv.properties || []).length; p++) {
359	    var prop = inv.properties[p];
360	    prop.currentPrice = Math.round(
361	      (prop.currentPrice || prop.buyPrice) *
362	        (1 + prop.appreciation + (Math.random() - 0.5) * 0.002),
363	    );
364	    if (state.player.day % 30 === 0) state.resources.cash += prop.rent || 0;
365	  }
366	
367	  // 汽车
368	  for (var c = 0; c < (inv.cars || []).length; c++) {
369	    var car = inv.cars[c];
370	    car.currentPrice = Math.round(
371	      (car.currentPrice || car.buyPrice) * (1 - car.depreciation),
372	    );
373	    if (state.player.day % 30 === 0 && state.resources.cash >= car.maintenance)
374	      state.resources.cash -= car.maintenance;
375	  }
376	}
