382	  if (!m) return;
383	  var cost = Math.round(m.price * shares * 100) / 100;
384	  if (state.resources.cash < cost) {
385	    StateManager.addMessage("现金不足", "danger");
386	    return;
387	  }
388	  state.resources.cash -= cost;
389	  var h = inv.stockHoldings.find(function (s) {
390	    return s.symbol === symbol;
391	  });
392	  if (h) {
393	    var total = h.shares + shares;
394	    h.avgPrice =
395	      Math.round(((h.avgPrice * h.shares + cost) / total) * 100) / 100;
396	    h.shares = total;
397	  } else
398	    inv.stockHoldings.push({
399	      symbol: symbol,
400	      shares: shares,
401	      avgPrice: m.price,
402	    });
403	  StateManager.addMessage("买入 " + symbol + " " + shares + "股", "success");
404	}
405	
406	function sellInvStock(symbol, shares) {
407	  var state = StateManager.getState();
408	  var inv = state.investment;
409	  var h = inv.stockHoldings.find(function (s) {
410	    return s.symbol === symbol;
411	  });
412	  if (!h || h.shares < shares) {
413	    StateManager.addMessage("持仓不足", "danger");
414	    return;
415	  }
416	  var m = inv.stockMarket[symbol];
417	  var revenue = Math.round(m.price * shares * 100) / 100;
418	  state.resources.cash += revenue;
419	  h.shares -= shares;
420	  if (h.shares <= 0)
421	    inv.stockHoldings = inv.stockHoldings.filter(function (s) {
422	      return s.symbol !== symbol;
423	    });
424	  StateManager.addMessage("卖出 " + symbol + " " + shares + "股", "success");
425	}
426	
427	function buyBtc(amount) {
428	  var state = StateManager.getState();
429	  var inv = state.investment;
430	  var cost = Math.round(inv.btcPrice * amount * 100) / 100;
431	  if (state.resources.cash < cost) {
432	    StateManager.addMessage("现金不足", "danger");
433	    return;
434	  }
435	  state.resources.cash -= cost;
436	  // 追踪加权平均成本
437	  var oldTotal = (inv.btcAvgCost || 0) * (inv.btcHoldings || 0);
438	  var newTotal = oldTotal + cost;
439	  inv.btcHoldings = Math.round((inv.btcHoldings + amount) * 10000) / 10000;
440	  inv.btcAvgCost =
441	    inv.btcHoldings > 0
442	      ? Math.round((newTotal / inv.btcHoldings) * 100) / 100
443	      : 0;
444	  StateManager.addMessage(
445	    "买入 " + amount + " BTC, 均价 ¥" + inv.btcAvgCost.toLocaleString(),
446	    "success",
447	  );
448	}
449	
450	function sellBtc(amount) {
451	  var state = StateManager.getState();
452	  var inv = state.investment;
453	  if (inv.btcHoldings < amount) {
454	    StateManager.addMessage("持仓不足", "danger");
455	    return;
456	  }
457	  var curPrice = inv.btcPrice;
458	  var revenue = Math.round(curPrice * amount * 100) / 100;
459	  var avgCost = inv.btcAvgCost || 0;
460	  var pl = avgCost > 0 ? Math.round((curPrice - avgCost) * amount) : 0;
461	  var plStr = pl !== 0 ? (pl > 0 ? " 📈+" : " 📉") + pl : "";
462	  state.resources.cash += revenue;
463	  inv.btcHoldings = Math.round((inv.btcHoldings - amount) * 10000) / 10000;
464	  // 清仓时重置成本
465	  if (inv.btcHoldings <= 0) inv.btcAvgCost = 0;
466	  StateManager.addMessage(
467	    "卖出 " +
468	      amount +
469	      " BTC, 到手 ¥" +
470	      Math.round(revenue).toLocaleString() +
471	      plStr,
472	    "success",
473	  );
474	}
475	
476	function buyProperty(propId) {
477	  var state = StateManager.getState();
478	  var inv = state.investment;
479	  var prop = PROPERTIES.find(function (p) {
480	    return p.id === propId;
481	  });
482	  if (!prop) return;
483	  if (state.resources.cash < prop.price) {
484	    StateManager.addMessage("现金不足", "danger");
485	    return;
486	  }
487	  state.resources.cash -= prop.price;
488	  inv.properties.push({
489	    id: prop.id,
490	    name: prop.name,
491	    type: prop.type,
492	    appreciation: prop.appreciation,
493	    rent: prop.rent,
494	    buyPrice: prop.price,
495	    currentPrice: prop.price,
496	    buyDay: state.player.day,
497	  });
498	  StateManager.addMessage("购入" + prop.name, "success");
499	}
