function renderSkillsTab(state, parent) {
  parent.innerHTML = "";
  const div = document.createElement("div");
  div.innerHTML =
    '<h3 style="color:var(--text-muted);margin-bottom:12px;">📚 技能</h3>';

  const grid = document.createElement("div");
  grid.className = "action-cards";
  grid.style.gridTemplateColumns = "repeat(auto-fill, minmax(180px, 1fr))";

  const skillNames = {
    cooking: "🍳 烹饪",
    repair: "🔧 维修",
    coding: "💻 编程",
    english: "🌐 英语",
    driving: "🚗 驾驶",
    sales: "💼 销售",
    management: "📋 管理",
    accounting: "📊 会计",
    electrician: "⚡ 电工",
    welding: "🔥 焊接",
  };

  for (const [key, skill] of Object.entries(state.skills)) {
    const card = document.createElement("div");
    card.className = "action-card";
    const name = skillNames[key] || key;
    const xpNeeded = (skill.level + 1) * 100;
    const xpPct = Math.min(100, Math.round((skill.xp / xpNeeded) * 100));
    // 查找哪些工作需要此技能
    var unlockedJobs = [];
    if (typeof STREET_JOBS !== "undefined") {
      for (var ji = 0; ji < STREET_JOBS.length; ji++) {
        var j = STREET_JOBS[ji];
        if (
          j.requirements &&
          j.requirements[key] &&
          skill.level >= j.requirements[key]
        ) {
          unlockedJobs.push(j);
        }
      }
    }
    var jobHints = "";
    if (unlockedJobs.length > 0) {
      jobHints =
        '<div style="font-size:9px;color:var(--success);margin-top:4px;">✅ 解锁: ' +
        unlockedJobs
          .slice(0, 3)
          .map(function (jj) {
            return jj.name;
          })
          .join(" / ") +
        "</div>";
    } else {
      // 显示需要此技能但尚未达到的工作
      var pendingJobs = [];
      if (typeof STREET_JOBS !== "undefined") {
        for (var pji = 0; pji < STREET_JOBS.length; pji++) {
          var pj = STREET_JOBS[pji];
          if (
            pj.requirements &&
            pj.requirements[key] &&
            skill.level < pj.requirements[key]
          ) {
            pendingJobs.push({ name: pj.name, need: pj.requirements[key] });
          }
        }
      }
      if (pendingJobs.length > 0) {
        jobHints =
          '<div style="font-size:9px;color:var(--text-muted);margin-top:4px;">🔒 待解锁: ' +
          pendingJobs
            .slice(0, 3)
            .map(function (pp) {
              return pp.name + "(需≥" + pp.need + ")";
            })
            .join(" / ") +
          "</div>";
      }
    }
    card.innerHTML = `
      <div class="card-title">${name}</div>
      <div class="card-desc">等级 ${skill.level} / 100</div>
      <div style="margin-top:6px;height:6px;background:rgba(255,255,255,0.05);border-radius:3px;">
        <div style="width:${xpPct}%;height:100%;background:${xpPct > 0 ? "var(--accent)" : "rgba(255,255,255,0.1)"};border-radius:3px;transition:width 0.3s"></div>
      </div>
      <div style="font-size:10px;color:var(--text-muted);margin-top:2px;">EXP: ${skill.xp}/${xpNeeded}</div>
      ${jobHints}
    `;
    grid.appendChild(card);
  }
  div.appendChild(grid);

  // 证书
  if (state.certificates.length > 0) {
    const certDiv = document.createElement("div");
    certDiv.style.marginTop = "16px";
    certDiv.innerHTML =
      '<h3 style="color:var(--text-muted);margin-bottom:8px;">📜 证书</h3>';
    const certList = document.createElement("div");
    certList.className = "flex gap-2";
    certList.style.flexWrap = "wrap";
    for (const certId of state.certificates) {
      const badge = document.createElement("span");
      badge.style.cssText =
        "padding:4px 10px;background:rgba(46,204,113,0.1);border:1px solid var(--success);border-radius:4px;font-size:11px;color:var(--success);";
      badge.textContent = certId;
      certList.appendChild(badge);
    }
    certDiv.appendChild(certList);
    div.appendChild(certDiv);
  }

  parent.appendChild(div);
  console.log("Skills tab rendered");
}

