    if (pendingJobs.length > 0) {
      jobHtml += '<div style="font-size:9px;color:var(--text-muted);margin-top:2px;">🔒待解锁: ' + pendingJobs.slice(0,3).map(function(pp){return pp.name+"(≥"+pp.need+")";}).join(" / ") + '</div>';
    }

    card.innerHTML =
