}

// 技能训练函数
function trainSkill(skillKey) {
  var state = StateManager.getState();
  var skill = state.skills[skillKey];
  if (!skill) return;
  if (state.resources.ap < 10) {
    StateManager.addMessage("⚡行动力不足(需10点),请休息后再来训练", "warning");
    return;
  }
  if (state.resources.cash < 20) {
    StateManager.addMessage("💰训练需要至少¥20(书本/材料费)", "warning");
    return;
  }
  // 消耗AP和金钱
  state.resources.ap -= 10;
  state.resources.cash -= 20;
  // 基础XP增益+智力加成
  var baseGain = 15 + Math.floor(Math.random() * 20);
  var intBonus = Math.floor(state.player.intelligence / 10) * 3;
  var xpGain = baseGain + intBonus;
  skill.xp += xpGain;
  // 升级判定
  var xpNeeded = (skill.level + 1) * 100;
  while (skill.xp >= xpNeeded && skill.level < 100) {
    skill.xp -= xpNeeded;
    skill.level += 1;
    xpNeeded = (skill.level + 1) * 100;
    StateManager.addMessage("🎉 " + (skillNamesCache[skillKey] || skillKey) + "升级到Lv." + skill.level + "!", "success");
    // 升级提升关联属性
    if (["physique","cooking","welding","repair","electrician"].indexOf(skillKey) >= 0) { state.player.physique = Math.min(100, state.player.physique + 1); }
    if (["coding","english","accounting","management"].indexOf(skillKey) >= 0) { state.player.intelligence = Math.min(100, state.player.intelligence + 1); }
    if (["driving","sales"].indexOf(skillKey) >= 0) { state.player.agility = Math.min(100, state.player.agility + 1); }
  }
  StateManager.addMessage("📚 训练了" + (skillNamesCache[skillKey] || skillKey) + ",EXP+" + xpGain + "(-⚡10 -💰¥20)", "success");
  consumeAP(10);
}

