  if ((state.resources.villageDebt || state.resources.debt) > 0) {
    var villageDebt = state.resources.villageDebt || state.resources.debt;
    var isNewbie = state.player.day <= 15;
    var dailyRate = isNewbie
      ? state.resources.dailyInterest / 2
      : state.resources.dailyInterest;
    var interest = Math.floor(villageDebt * dailyRate);
    if (interest > 0) {
      state.resources.villageDebt =
        (state.resources.villageDebt || villageDebt) + interest;
      state.resources.villageDebtInterest =
        (state.resources.villageDebtInterest || 0) + interest;
      state.resources.debt =
        (state.resources.villageDebt || 0) + (state.resources.bankDebt || 0);
      StateManager.addMessage(
        '🏘️ 村长债务利息：+¥' + interest + '（欠村长 ¥' + (state.resources.villageDebt || 0).toLocaleString() + '）',
        "warning"
      );
    }
  }
  // 银行债务利息
  if ((state.resources.bankDebt || 0) > 0) {
    var bankInterest = Math.floor(
      state.resources.bankDebt * state.resources.dailyInterest
    );
    if (bankInterest > 0) {
      state.resources.bankDebt += bankInterest;
      state.resources.debt =
        (state.resources.villageDebt || 0) + state.resources.bankDebt;
      StateManager.addMessage('🏦 银行贷款利息：+¥' + bankInterest, "warning");
    }
  }
  // 银行存款利息（含会计技能加成）
  if (state.resources.bankBalance > 0) {
    var isNewbie = state.player.day <= 15;
    var baseRate = isNewbie ? 0.002 : 0.001;
    // 会计技能加成
    var acctBonus = 0;
    if (typeof getBankRateBonus === 'function') {
      acctBonus = getBankRateBonus((state.skills.accounting && state.skills.accounting.level) || 0);
    }
    var bankRate = baseRate + acctBonus;
    var bankInterest = Math.floor(state.resources.bankBalance * bankRate);
    if (bankInterest > 0) state.resources.bankBalance += bankInterest;
  }
}

