      "</div>" +
      '<div class="card-desc">Lv.' +
      skill.level +
      " / 100</div>" +
      '<div style="margin-top:6px;height:6px;background:rgba(255,255,255,0.05);border-radius:3px;">' +
      '<div style="width:' +
      xpPct +
      "%;height:100%;background:" +
      (xpPct > 0 ? "var(--accent)" : "rgba(255,255,255,0.1)") +
      ';border-radius:3px;"></div></div>' +
      '<div style="font-size:10px;color:var(--text-muted);margin-top:2px;">EXP: ' +
      skill.xp +
      "/" +
      xpNeeded +
      "</div>" +
      jobHtml +
      '<div style="margin-top:8px;font-size:11px;color:var(--warning);font-weight:bold;">⚡ 点击训练</div>';

    // 点击训练技能
    (function (skillKey) {
      card.addEventListener("click", function () {
        var st = StateManager.getState();
        var sk = st.skills[skillKey];
        if (!sk) return;
        if (st.resources.ap < 10) {
          StateManager.addMessage(
            "⚠️ 行动力不足(需10点)，请休息后再来训练",
            "warning",
          );
          return;
        }
        if (st.resources.cash < 20) {
          StateManager.addMessage("⚠️ 训练需要¥20书本费，钱不够", "warning");
          return;
        }
        st.resources.ap -= 10;
        st.resources.cash -= 20;
        var baseGain = 15 + Math.floor(Math.random() * 20);
        var intBonus = Math.floor((st.player.intelligence || 0) / 10) * 3;
        var xpGain = baseGain + intBonus;
        sk.xp += xpGain;
        // 升级处理
        while (sk.xp >= (sk.level + 1) * 100 && sk.level < 100) {
          sk.xp -= (sk.level + 1) * 100;
          sk.level += 1;
          StateManager.addMessage(
            "🎉 " +
              (skillNames[skillKey] || skillKey) +
              " 升级到 Lv." +
              sk.level +
              "！",
            "success",
          );
          // 升级提升关联属性
          if (
            ["physique", "cooking", "welding", "repair", "electrician"].indexOf(
              skillKey,
            ) >= 0
          ) {
            st.player.physique = Math.min(100, (st.player.physique || 0) + 1);
          }
          if (
            ["coding", "english", "accounting", "management"].indexOf(
              skillKey,
            ) >= 0
          ) {
            st.player.intelligence = Math.min(
