1151	/**
1152	 * 技能加权收入倍率
1153	 * 根据工作类型，玩家相关技能等级会提升收入。
1154	 * 每10级技能提升约5%收入，上限+50%（Lv.100）。
1155	 * 减少纯RNG依赖，奖励技能投资。
1156	 */
1157	function getSkillPayBonus(jobId, state) {
1158	  const s = state.skills;
1159	  const skillMap = {
1160	    // 维修类 -> repair 技能
1161	    repair_service: { key: "repair", weight: 1.0 },
1162	    skilled_labor_construction: { key: "repair", weight: 0.6 },
1163	    // 摆摊/销售类 -> sales 技能
1164	    street_vending_food: { key: "sales", weight: 0.8 },
1165	    street_vending_goods: { key: "sales", weight: 1.0 },
1166	    food_stall: { key: "cooking", weight: 0.9 },
1167	    // 配送类 -> agility
1168	    delivery_rider: { key: "agility", weight: 0.7 },
1169	    package_delivery: { key: "agility", weight: 0.6 },
1170	    // 仓库/体力类 -> physique
1171	    warehouse_worker: { key: "physique", weight: 0.5 },
1172	    manual_labor_construction: { key: "physique", weight: 0.6 },
1173	    factory_work_assembly: { key: "physique", weight: 0.5 },
1174	    // 保安 -> physique
1175	    security_guard: { key: "physique", weight: 0.3 },
1176	    // 理发 -> repair(手艺)
1177	    barber: { key: "repair", weight: 0.5 },
1178	    // 清洁 -> physique
1179	    cleaning_service: { key: "physique", weight: 0.3 },
1180	    // 家教 -> intelligence
1181	    tutoring: { key: "intelligence", weight: 0.8 },
1182	    // 表演 -> sales(吸引打赏)
1183	    street_performer: { key: "sales", weight: 0.5 },
1184	  };
1185	
1186	  const mapping = skillMap[jobId];
1187	  if (!mapping) return 1.0;
1188	
1189	  // 兼容属性键和技能键
1190	  let effectiveLevel = 0;
1191	  const attrKeys = ["physique", "intelligence", "agility", "mental"];
1192	  if (attrKeys.includes(mapping.key)) {
1193	    effectiveLevel = state.player[mapping.key] || 0;
1194	  } else if (s[mapping.key]) {
1195	    effectiveLevel = s[mapping.key].level || 0;
1196	  }
1197	
1198	  // 每10级 +5%收入，权重调节
1199	  const bonus = (effectiveLevel / 10) * 0.05 * mapping.weight;
1200	  return 1.0 + Math.max(0, Math.min(0.35, bonus));
1201	}
