/** 每日财务结算（利息+储蓄），单独提取供skip_day复用 */
function settleDailyFinance(state) {
  // 村长债务利息（每天滚入本金，新人前15天减半）
  if ((state.resources.villageDebt || state.resources.debt) > 0) {
    var villageDebt = state.resources.villageDebt || state.resources.debt;
    var isNewbie = state.player.day <= 15;
    var dailyRate = isNewbie
      ? state.resources.dailyInterest / 2
      : state.resources.dailyInterest;
    var interest = Math.floor(villageDebt * dailyRate);
    if (interest > 0) {
      state.resources.villageDebt =
        (state.resources.villageDebt || villageDebt) + interest;
      state.resources.villageDebtInterest =
        (state.resources.villageDebtInterest || 0) + interest;
      state.resources.debt =
        (state.resources.villageDebt || 0) + (state.resources.bankDebt || 0);
      StateManager.addMessage(
        '🏘️ 村长债务利息：+¥' + interest + '（欠村长 ¥' + (state.resources.villageDebt || 0).toLocaleString() + '）',
        "warning"
      );
    }
  }
  // 银行债务利息
  if ((state.resources.bankDebt || 0) > 0) {
    var bankInterest = Math.floor(
      state.resources.bankDebt * state.resources.dailyInterest
    );
    if (bankInterest > 0) {
      state.resources.bankDebt += bankInterest;
      state.resources.debt =
        (state.resources.villageDebt || 0) + state.resources.bankDebt;
      StateManager.addMessage('🏦 银行贷款利息：+¥' + bankInterest, "warning");
    }
  }
  // 银行存款利息（含会计技能加成）
  if (state.resources.bankBalance > 0) {
    var isNewbie = state.player.day <= 15;
    var baseRate = isNewbie ? 0.002 : 0.001;
    // 会计技能加成
    var acctBonus = 0;
    if (typeof getBankRateBonus === 'function') {
      acctBonus = getBankRateBonus((state.skills.accounting && state.skills.accounting.level) || 0);
    }
    var bankRate = baseRate + acctBonus;
    var bankInterest = Math.floor(state.resources.bankBalance * bankRate);
    if (bankInterest > 0) state.resources.bankBalance += bankInterest;
  }
}

function endDay() {
  const state = StateManager.getState();

  state.player.day++;
  // 重置行动力
  state.player.actionPoints = state.player.maxActionPoints;
  state.player.timeSlot = "morning";

  // 使用需求系统模块
  if (typeof applyNeedsDecay === "function") applyNeedsDecay(state);
  else {
    state.needs.hunger = Math.max(0, state.needs.hunger - 18);
    state.needs.hygiene = Math.max(0, state.needs.hygiene - 8);
  }

  // 状态交叉影响（饥饿→疲劳→心情的多米诺效应）
  if (typeof applyStatusInteractions === "function") applyStatusInteractions(state);

  // 睡眠恢复（基础25 + 住所加成）— 心情差时恢复效率减半
  var house = getCurrentHousing(state);
  var fatigueRecovery = house.fatigueRecovery;
  var recoveryPenalty = state._fatigueRecoveryPenalty || 1.0;
  if (recoveryPenalty < 1.0) {
    StateManager.addMessage("😢 心情低落，睡眠质量很差，疲劳恢复减半。", "warning");
  }
  state.needs.fatigue = Math.max(0, state.needs.fatigue - Math.round(fatigueRecovery * recoveryPenalty));
  // 清理临时标记
  delete state._fatigueRecoveryPenalty;
  state.needs.hygiene = Math.min(
    100,
    state.needs.hygiene + (house.hygieneBonus || 0),
  );
  state.needs.happiness = Math.max(
    0,
    Math.min(100, state.needs.happiness - 3 + (house.happinessBonus || 0)),
  );

  // 扣房租
  if (house.rent > 0) {
    if (state.resources.cash >= house.rent) {
      state.resources.cash -= house.rent;
    } else {
      StateManager.addMessage(
        `⚠️ 付不起房租 ¥${house.rent}！被赶回流落街头。`,
        "danger",
      );
      state.housing.tier = 0;
      state.inventory.capacity = 20 + (state.housing?.storageCapacity || 0);
    }
  }
  // 扣仓库租金
  if (state.housing?.storageRented && state.housing?.storageCapacity > 0) {
    const storageRent = state.housing.storageCapacity >= 500 ? 50 : 20;
    if (state.resources.cash >= storageRent) {
      state.resources.cash -= storageRent;
    } else {
      StateManager.addMessage("⚠️ 付不起仓库租金，仓库被收回。", "danger");
      state.housing.storageRented = false;
      state.housing.storageCapacity = 0;
      const baseCap = [20, 50, 100, 200][state.housing.tier || 0];
      state.inventory.capacity = baseCap;
    }
  }

  // 伤病结算
  if (typeof tickHealthStatus === "function") tickHealthStatus(state);
  else {
    if (!state.status.sick && !state.status.injured)
      state.status.health = Math.min(100, state.status.health + 1);
    if (state.status.sick) {
      state.status.health = Math.max(0, state.status.health - 3);
      if (Math.random() < 0.1) state.status.sick = false;
    }
    if (state.status.injured) {
      state.status.health = Math.max(0, state.status.health - 2);
      if (Math.random() < 0.05) state.status.injured = false;
    }
  }

  // 需求阈值检查
  if (typeof checkNeedsThresholds === "function") checkNeedsThresholds(state);

  // 极端状态检测（饿晕跳过全天/过劳强制结束/病危送医）
  var extremeResult = (typeof checkExtremeConditions === "function")
    ? checkExtremeConditions(state)
    : null;
  if (extremeResult === 'skip_day') {
    // 跳过当天剩余结算（投资tick/价格更新/新闻），但利息和自动存档必须执行
    StateManager.addMessage(
      "🌙 第" + state.player.day + "天在昏迷中过去了...",
      "danger"
    );
    // 仍然结算利息和存档
    settleDailyFinance(state);
    autoSave();
    return;
  }

  // 情绪判定
  if (typeof determineEmotionalState === "function")
    determineEmotionalState(state);

  // 每日财务结算（债务利息+存款利息，含会计技能加成）
  settleDailyFinance(state);

  // 每3天更新价格
  if (state.player.day - state.trade.lastPriceUpdate >= 3) {
    if (typeof updateAllPrices === "function") updateAllPrices(state);
  }

  // 投资每日tick
  if (typeof tickInvestmentDaily === "function") tickInvestmentDaily(state);

  // 天气更新
  if (typeof rollWeather === "function") rollWeather(state);

  // 新闻事件
  if (typeof rollDailyNews === "function") rollDailyNews(state);
  else if (Math.random() < 0.1) triggerRandomEvent(state);

  // 城管热度每日衰减
  if (state.chengguan) {
    state.chengguan.heat = Math.max(
      0,
      state.chengguan.heat - 5 - Math.floor(Math.random() * 5),
    );
  }

  // 清理过期效果
  if (typeof dailyCleanup === "function") dailyCleanup(state);

  // 每年年龄增长
  if (state.player.day % 365 === 0) {
    state.player.age++;
    StateManager.addMessage(
      `🎂 又过了一年，你现在${state.player.age}岁了。`,
      "event",
    );
  }

  // 胜利路线检查（多种胜利条件）
  checkVictoryPaths(state);

  // 失败条件检查
