/* ================================================================
   城市浮生记 (City Life Story) — 全局样式
   设计参考: 互联网大厂模拟器 (bigtech-simulator.com)
   主题: 扁平化蓝色科技风
   ================================================================ */

/* ====== CSS 变量 / 主题 ====== */
:root {
  --bg-primary: #0a1628;
  --bg-secondary: #0f1d33;
  --bg-card: #152238;
  --bg-card-hover: #1a2f4a;
  --bg-sidebar: #0d1a2d;
  --bg-input: #0f1d33;

  --border: #1e3a5f;
  --border-light: #264b73;

  --text-primary: #e8edf5;
  --text-secondary: #8ba4c7;
  --text-muted: #5a7899;

  --accent: #00b4d8;
  --accent-glow: rgba(0, 180, 216, 0.15);
  --accent-hover: #0096b5;

  --success: #2ecc71;
  --success-bg: rgba(46, 204, 113, 0.1);
  --danger: #e74c3c;
  --danger-bg: rgba(231, 76, 60, 0.1);
  --warning: #f39c12;
  --warning-bg: rgba(243, 156, 18, 0.1);
  --info: #3498db;

  --hair-color: #7ec8e3;
  --mental-color: #c3b1e1;
  --kpi-color: #f9ca24;
  --risk-color: #e74c3c;
  --physique-color: #e67e22;
  --intelligence-color: #3498db;
  --agility-color: #2ecc71;
  --mental-attrs-color: #9b59b6;

  --font-mono: "Consolas", "Courier New", monospace;
  --font-sans:
    -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC",
    "Microsoft YaHei", sans-serif;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  --sidebar-width: 280px;
  --header-height: 48px;
  --transition: 0.2s ease;
}

/* ====== Reset ====== */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  height: 100%;
  overflow: hidden;
}

body {
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  color: var(--text-primary);
  background: var(--bg-primary);
  -webkit-font-smoothing: antialiased;
}

/* ====== Scrollbar ====== */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--border-light);
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

/* ====== App Layout (CSS Grid) ====== */
#app {
  display: grid;
  grid-template-rows: var(--header-height) 1fr;
  grid-template-columns: var(--sidebar-width) 1fr;
  grid-template-areas:
    "header header"
    "sidebar main";
  height: 100vh;
  max-height: 100vh;
}

