332	/* ====== Main Content ====== */
333	#main {
334	  grid-area: main;
335	  display: flex;
336	  flex-direction: column;
337	  overflow: hidden;
338	  background: var(--bg-primary);
339	}
340	
341	/* --- Tab Bar --- */
342	#tab-bar {
343	  display: flex;
344	  background: var(--bg-secondary);
345	  border-bottom: 1px solid var(--border);
346	  padding: 0 12px;
347	  flex-shrink: 0;
348	}
349	
350	.tab-btn {
351	  padding: 10px 20px;
352	  font-size: 13px;
353	  color: var(--text-muted);
354	  background: none;
355	  border: none;
356	  border-bottom: 2px solid transparent;
357	  cursor: pointer;
358	  transition: all var(--transition);
359	  font-family: var(--font-sans);
360	}
361	
362	.tab-btn:hover {
363	  color: var(--text-primary);
364	  background: rgba(255, 255, 255, 0.03);
365	}
366	
367	.tab-btn.active {
368	  color: var(--accent);
369	  border-bottom-color: var(--accent);
370	}
371	
372	/* --- Content Area --- */
373	#content-area {
374	  flex: 1;
375	  overflow-y: auto;
376	  padding: 16px;
377	  display: flex;
378	  flex-direction: column;
379	  gap: 16px;
380	}
381	
382	/* --- Time Slot Indicator --- */
383	#time-slot-indicator {
384	  display: flex;
385	  align-items: center;
386	  gap: 8px;
387	  padding: 8px 16px;
388	  background: var(--bg-card);
389	  border-radius: var(--radius-md);
390	  font-size: 13px;
391	  flex-shrink: 0;
392	}
393	
394	.time-slot-badge {
395	  padding: 2px 10px;
396	  border-radius: var(--radius-sm);
397	  font-size: 11px;
398	  font-weight: 600;
399	}
400	
401	.time-slot-badge.morning {
402	  background: rgba(243, 156, 18, 0.2);
403	  color: var(--warning);
404	}
405	.time-slot-badge.afternoon {
406	  background: rgba(52, 152, 219, 0.2);
407	  color: var(--info);
408	}
409	.time-slot-badge.evening {
410	  background: rgba(142, 68, 173, 0.2);
411	  color: #9b59b6;
412	}
413	
414	/* --- Action Cards Grid --- */
415	.action-cards {
416	  display: grid;
417	  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
418	  gap: 10px;
419	}
420	
421	.action-card {
422	  background: var(--bg-card);
423	  border: 1px solid var(--border);
424	  border-radius: var(--radius-md);
425	  padding: 14px;
426	  cursor: pointer;
427	  transition: all var(--transition);
428	}
429	
430	.action-card:hover {
431	  background: var(--bg-card-hover);
432	  border-color: var(--accent);
433	  transform: translateY(-1px);
434	  box-shadow: 0 4px 12px rgba(0, 180, 216, 0.1);
435	}
436	
437	.action-card.disabled {
438	  opacity: 0.4;
439	  cursor: not-allowed;
440	}
441	
442	.action-card.disabled:hover {
443	  border-color: var(--border);
444	  transform: none;
445	  box-shadow: none;
446	}
447	
448	.action-card .card-icon {
449	  font-size: 24px;
450	  margin-bottom: 6px;
