/* ====== Animations ====== */
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

.pulse {
  animation: pulse 2s infinite;
}

/* ====== Welcome Screen ====== */
.welcome-screen {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100vh;
  gap: 24px;
  text-align: center;
}

.welcome-title {
  font-size: 36px;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 1px;
}

.welcome-subtitle {
  font-size: 14px;
  color: var(--text-muted);
  max-width: 400px;
  line-height: 1.6;
}

.welcome-buttons {
  display: flex;
  gap: 12px;
}

/* ====== Tab Content Panels ====== */
.tab-panel {
  display: none;
}

.tab-panel.active {
  display: block;
}

/* ====== City Map ====== */
.city-map {
  position: relative;
}

.city-map .map-node {
  animation: mapFadeIn 0.4s ease backwards;
}

.city-map .map-node:nth-child(1) {
  animation-delay: 0.02s;
}
.city-map .map-node:nth-child(2) {
  animation-delay: 0.04s;
}
.city-map .map-node:nth-child(3) {
  animation-delay: 0.06s;
}
.city-map .map-node:nth-child(4) {
  animation-delay: 0.08s;
}
.city-map .map-node:nth-child(5) {
  animation-delay: 0.1s;
}
.city-map .map-node:nth-child(6) {
  animation-delay: 0.12s;
}
.city-map .map-node:nth-child(7) {
  animation-delay: 0.14s;
}
.city-map .map-node:nth-child(8) {
  animation-delay: 0.16s;
}
.city-map .map-node:nth-child(9) {
  animation-delay: 0.18s;
}
.city-map .map-node:nth-child(10) {
  animation-delay: 0.2s;
}
.city-map .map-node:nth-child(11) {
  animation-delay: 0.22s;
}

@keyframes mapFadeIn {
  from {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.8);
  }
  to {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
}

/* Nearby locations sidebar widget */
.nearby-loc-item {
  cursor: pointer;
  transition: all 0.2s ease;
}

.nearby-loc-item:hover {
  border-color: var(--accent) !important;
  background: var(--bg-card-hover) !important;
  transform: translateX(2px);
}

/* Location services badges area */
#location-services {
  min-height: 20px;
}

/* ====== Responsive: Mobile ====== */
@media (max-width: 768px) {
  #app {
    grid-template-columns: 1fr;
    grid-template-areas:
      "header"
      "main";
  }

  #sidebar {
    position: fixed;
    left: -100%;
    top: var(--header-height);
    bottom: 0;
    width: 280px;
    z-index: 200;
    transition: left 0.3s ease;
    box-shadow: 2px 0 8px rgba(0, 0, 0, 0.3);
  }

  #sidebar.open {
    left: 0;
  }

  .action-cards {
    grid-template-columns: 1fr;
  }

  .header-stats {
    gap: 10px;
  }

  .header-stat .label {
    display: none;
  }

  #mobile-menu-btn {
    display: flex !important;
  }

  /* 地图节点放大，触控友好 */
  .map-node {
    min-width: 70px !important;
    padding: 10px 14px !important;
    font-size: 12px !important;
  }

